class stringx
{
public:
  const char *c_str() const;
  stringx &operator=(const stringx &);
};

#include <assert.h>

stringx operator+(const char *, const stringx &);

extern "C" int strncmp(const char *, const char *, unsigned int);
extern "C" unsigned int strlen(const char *);
extern "C" int sceOpen(char *, int);

extern const char *nglHostPrefix;
extern bool g_error_condition;
extern int g_try_count;

asm(".equ nglHostPrefix, 0x004AB798");
asm(".equ g_error_condition, 0x003FE3A4");
asm(".equ g_try_count, 0x003FE3A8");

#define MAX_DISK_OP_TRIES 300
#define RETRY_LOOP_ENTRY g_try_count = 0; do{
#define RETRY_LOOP_WHILE(cond) g_error_condition = ((cond)); g_try_count++; }while( ( g_try_count < MAX_DISK_OP_TRIES ) && g_error_condition );
#define ON_RETRY_ERROR if( g_error_condition )

class os_file
{
public:
  enum mode_flags
  {
    FILE_READ = 1,
    FILE_WRITE = 2,
    FILE_MODIFY = 3,
    FILE_APPEND = 4
  };

  bool try_to_open_from_disk();

private:
  stringx name;
  int flags;
  bool opened;
  bool eof;
  bool from_cd;
  union
  {
    int host;
    char cd[36];
  } io;
  int curr_fp;
};

bool os_file::try_to_open_from_disk()
{
  // read from host disk

  // until we implement a DVD/CD reader, we'll get all of our data from the host
  if (strncmp(name.c_str(), nglHostPrefix, strlen(nglHostPrefix)) != 0)
    name=nglHostPrefix+name;

//  nglPrintf("opening file %s on the host disk\n", name.c_str());
  int mode=-1;

  // convert the flags to Sony's fileio flags 
  switch (flags)
  {
    case FILE_READ:   mode=1;              break;
    case FILE_WRITE:  mode=2 | 0x0200 | 0x0400;  break;
    case FILE_APPEND: mode=2 | 0x0200 | 0x0008; break;
    case FILE_MODIFY: mode=3;                break;
  }
  assert(mode!=-1);

  // attempt to open the file
  RETRY_LOOP_ENTRY;
    io.host = sceOpen((char *)name.c_str(), mode);
  RETRY_LOOP_WHILE( io.host < 0 );  

  ON_RETRY_ERROR return false;

  opened = true;
  eof = false;
  from_cd = false;
  curr_fp = 0;

  return opened;
}
